package io.github.jesterportfolio.hearth.verification;

import java.util.*;import java.util.concurrent.*;import java.nio.file.*;
import org.bukkit.*;import org.bukkit.plugin.java.JavaPlugin;
import com.sk89q.worldedit.math.BlockVector3;import com.sk89q.worldguard.protection.flags.Flags;import com.sk89q.worldguard.domains.Association;
import io.github.jesterportfolio.hearth.survival.*;import io.github.jesterportfolio.hearth.survival.housing.*;import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;import io.github.jesterportfolio.hearth.persistence.*;import io.github.jesterportfolio.hearth.inventory.PaperInventoryCodec;import org.bukkit.inventory.ItemStack;

/** 실제 PG/WG/개인 Paper 월드 계약 검사입니다. Player/클릭/인증은 합성하지 않습니다. */
public final class HousingVerification{
 private static final UUID OWNER=new UUID(0x484f4d45,1),RESIDENT=new UUID(0x484f4d45,2),VISITOR=new UUID(0x484f4d45,3);private HousingVerification(){}
 private static void check(JavaPlugin p,boolean ok,String name){if(!ok)throw new IllegalStateException("HOUSING_CHECK_"+name);p.getLogger().info("HEARTH_HOUSING_CHECK PASS "+name);}
 private static <T>CompletionStage<T> on(CompletionStage<T> f,HousingRuntime h){return f.thenApplyAsync(v->v,h.owner);}
 private static boolean build(World w,int x,int y,int z,UUID player){return HousingProtection.manager(w).getApplicableRegions(BlockVector3.at(x,y,z)).testState(regions->{if(regions.stream().anyMatch(r->r.getOwners().contains(player)))return Association.OWNER;if(regions.stream().anyMatch(r->r.getMembers().contains(player)))return Association.MEMBER;return Association.NON_MEMBER;},Flags.BUILD);}
 public static CompletionStage<Void> run(JavaPlugin p,SurvivalRuntime runtime,String action){final Path root;try{root=IsolatedPaths.require(Path.of(System.getProperty("hearth.housing.verification.root","")),"hearth-native-economy-run.");if(!Set.of("prepare","resume").contains(action)||!Path.of("").toRealPath().equals(root.resolve("server"))||!Files.readString(root.resolve(".hearth-housing-isolated")).equals("Hearth housing isolated v1\n")||!Bukkit.getOnlinePlayers().isEmpty()||!Bukkit.getOnlineMode()||!Bukkit.hasWhitelist()||!Bukkit.getIp().equals("127.0.0.1")||runtime.housing().state()!=HousingRuntime.State.READY)throw new IllegalStateException("HOUSING_PROBE_GATE");Files.createFile(root.resolve("housing-probe-"+action+".started"));}catch(Exception error){return CompletableFuture.failedFuture(error);}var h=runtime.housing();return on(h.economy.database().module("housing_probe_directory",c->{try(var st=c.createStatement();var r=st.executeQuery("SHOW data_directory")){if(!r.next()||!Path.of(r.getString(1)).toRealPath().equals(root.resolve("data")))throw new IllegalStateException("HOUSING_PROBE_DATABASE");}return null;}),h).thenCompose(v->action.equals("prepare")?prepare(p,h,root):resume(p,h,root));}
 private static CompletionStage<Void> prepare(JavaPlugin p,HousingRuntime h,Path root){var e=h.economy;var owner=e.store.context(e.settings.realm(),OWNER);var resident=e.store.context(e.settings.realm(),RESIDENT);var visitor=e.store.context(e.settings.realm(),VISITOR);var empty=new PaperInventoryCodec().encode(new ItemStack[41]);CompletionStage<Void> start=CompletableFuture.completedFuture(null);for(var ctx:List.of(owner,resident,visitor))start=start.thenCompose(v->e.store.ensureAccount(ctx,empty).thenAccept(a->{if(a.balance()!=0)throw new IllegalStateException("INITIAL_BALANCE");}));
  return on(start,h).thenCompose(v->on(e.database().module("housing_owned_fixture_fund",c->{try(var s=c.prepareStatement("UPDATE hearth_economy.account SET balance=5000 WHERE realm_id=? AND player_uuid=?")){s.setObject(1,e.settings.realm());s.setObject(2,OWNER);if(s.executeUpdate()!=1)throw new IllegalStateException("HOUSING_FIXTURE_OWNER");}return null;}),h)).thenCompose(v->h.provision(owner,0,-1,new UUID(0x484f5553,1),()->true,()->{})).thenCompose(first->{var world=Bukkit.getWorld(first.world());check(p,first.phase()==Phase.ACTIVE&&first.width()==32&&world!=null,"actual_private_flat_world_created_protected_and_activated");int y=h.worlds.entry(first).getBlockY();world.getBlockAt(5,y,5).setType(Material.GLASS,false);check(p,build(world,5,y,5,OWNER)&&!build(world,5,y,5,RESIDENT)&&!build(world,20,y,20,OWNER),"actual_WG_queries_allow_owner_and_deny_nonmember_or_outside_boundary");return on(e.store.account(owner),h).thenAccept(a->check(p,a.balance()==4900&&a.inventory().payload().equals(empty),"purchase_debits_once_without_replacing_native_inventory")).thenCompose(v->h.provision(owner,1,first.revision(),new UUID(0x484f5553,2),()->true,()->{})).thenCompose(expanded->{check(p,expanded.world().equals(first.world())&&expanded.seed()==first.seed()&&world.getBlockAt(5,y,5).getType()==Material.GLASS&&world.getWorldBorder().getSize()==64,"expansion_preserves_world_UUID_seed_and_existing_building");return on(e.store.account(owner),h).thenAccept(a->check(p,a.balance()==4600,"expansion_charges_only_three_hundred_difference")).thenApply(v->expanded);});})
  .thenCompose(house->h.store.invite(owner,house.id(),house.revision(),RESIDENT,Role.RESIDENT,()->true).thenCompose(v->h.refresh()).thenComposeAsync(v->{var latest=h.house(house.id()).orElseThrow();return h.store.accept(resident,latest.id(),latest.revision(),true,()->true);},h.owner).thenCompose(v->h.refresh()).thenComposeAsync(v->{var latest=h.house(house.id()).orElseThrow();return h.store.invite(owner,latest.id(),latest.revision(),VISITOR,Role.VISITOR,()->true);},h.owner).thenCompose(v->h.refresh()).thenComposeAsync(v->{var latest=h.house(house.id()).orElseThrow();return h.store.accept(visitor,latest.id(),latest.revision(),true,()->true);},h.owner).thenCompose(v->h.refresh()).thenComposeAsync(v->{var latest=h.house(house.id()).orElseThrow();return h.worlds.apply(latest,h.snapshot()).thenApply(vv->latest);},h.owner))
  .thenCompose(house->{var world=Bukkit.getWorld(house.world());int y=h.worlds.entry(house).getBlockY();check(p,build(world,5,y,5,RESIDENT)&&!build(world,5,y,5,VISITOR)&&h.snapshot().enter(VISITOR,house),"actual_WG_member_build_and_readonly_visitor_access_are_distinct");return h.target(RESIDENT,house.id()).thenAccept(at->check(p,at.getWorld()==world&&Bukkit.getOnlinePlayers().isEmpty(),"shared_home_load_is_independent_of_owner_online_state")).thenCompose(v->h.store.remove(owner,house.id(),house.revision(),RESIDENT,()->true)).thenCompose(v->h.refresh()).thenComposeAsync(v->{var latest=h.house(house.id()).orElseThrow();return h.worlds.apply(latest,h.snapshot()).thenApply(vv->latest);},h.owner);})
  .thenCompose(house->{var world=Bukkit.getWorld(house.world());int y=h.worlds.entry(house).getBlockY();check(p,!build(world,5,y,5,RESIDENT)&&!h.snapshot().enter(RESIDENT,house),"revoked_resident_is_removed_from_WG_and_cached_entry_authority");return h.store.claimPlot(owner,()->true).thenCompose(v->h.refresh()).thenRunAsync(()->{var base=h.boundary.entry(SurvivalWorld.RESIDENCE);var plot=h.settings.plots().getFirst();check(p,build(base.getWorld(),base.getBlockX()+plot.x()+1,base.getBlockY()+1,base.getBlockZ()+plot.z()+1,OWNER)&&!build(base.getWorld(),base.getBlockX()+plot.x()+1,base.getBlockY()+1,base.getBlockZ()+plot.z()+1,VISITOR)&&!build(base.getWorld(),base.getBlockX(),base.getBlockY()+1,base.getBlockZ(),OWNER),"public_plot_owner_can_build_only_in_assigned_region");},h.owner).thenCompose(v->h.worlds.unload(house.id())).thenRun(()->check(p,Bukkit.getWorld(house.world())==null,"idle_world_unloads_without_deleting_ownership_or_world_files")).thenCompose(v->h.target(OWNER,house.id())).thenAccept(at->{check(p,at.getWorld().getUID().equals(house.world())&&at.getWorld().getBlockAt(5,at.getBlockY(),5).getType()==Material.GLASS,"on_demand_reload_preserves_existing_building_and_world_identity");var saved=new Properties();saved.setProperty("house",house.id().toString());saved.setProperty("world",house.world().toString());saved.setProperty("seed",Long.toString(house.seed()));saved.setProperty("revision",Long.toString(house.revision()));saved.setProperty("y",Integer.toString(at.getBlockY()));try(var out=Files.newBufferedWriter(root.resolve("housing-expected.properties"),StandardOpenOption.CREATE_NEW)){saved.store(out,"No Player; actual PG/WG/Paper worlds");}catch(Exception error){throw new CompletionException(error);}});});
 }
 private static CompletionStage<Void> resume(JavaPlugin p,HousingRuntime h,Path root){var expected=new Properties();try(var r=Files.newBufferedReader(root.resolve("housing-expected.properties"))){expected.load(r);}catch(Exception e){return CompletableFuture.failedFuture(e);}var house=h.house(UUID.fromString(expected.getProperty("house"))).orElseThrow();check(p,house.phase()==Phase.ACTIVE&&house.world().toString().equals(expected.getProperty("world"))&&house.seed()==Long.parseLong(expected.getProperty("seed"))&&house.revision()==Long.parseLong(expected.getProperty("revision")),"second_JVM_restores_exact_house_owner_tier_and_identity");check(p,!h.snapshot().enter(RESIDENT,house)&&h.snapshot().enter(VISITOR,house)&&h.snapshot().plots().containsKey(OWNER),"second_JVM_restores_revoked_roles_visitor_and_public_plot");return h.target(OWNER,house.id()).thenCompose(at->{check(p,at.getWorld().getBlockAt(5,Integer.parseInt(expected.getProperty("y")),5).getType()==Material.GLASS&&at.getWorld().getWorldBorder().getSize()==64,"second_JVM_keeps_building_expanded_border_and_WG_protection");return h.worlds.setEntry(house,at).thenComposeAsync(v->{check(p,SurvivalWorlds.safe(h.worlds.entry(house)),"saved_home_entry_remains_pinned_after_same_chunk_reassignment");return on(h.economy.store.account(h.economy.store.context(h.economy.settings.realm(),OWNER)),h);},h.owner);}).thenAccept(a->check(p,a.balance()==4600,"second_JVM_never_recharges_purchase_or_expansion")).thenCompose(v->on(io.github.jesterportfolio.hearth.economy.HousingStore.inspectExisting(h.economy.database(),h.economy.store,h.economy.store.context(h.economy.settings.realm(),OWNER),new UUID(0x484f5553,1)),h)).thenAccept(r->check(p,r.isPresent()&&r.get().paid(),"readonly_receipt_inspection_does_not_require_runtime_initialization"));}
}
